ruleContent.content:
@js:
let t = result;
// 优先取 #readerContent
let m = t.match(/id=["']readerContent["'][^>]*>([\s\S]*?)<\/div>/i);
if (m) t = m[1];
else {
  m = t.match(/class=["']entry-content["'][^>]*>([\s\S]*?)<\/div>/i);
  if (m) t = m[1];
}
// 清理
t = t.replace(/<br\s*\/?>/gi, '\n')
     .replace(/<[^>]+>/g, '')
     .replace(/&nbsp;/g, ' ')
     .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
     .replace(/相關閱讀[\s\S]*/g, '')
     .replace(/热门TAG[\s\S]*/g, '')
     .replace(/返回上一頁[\s\S]*/g, '')
     .replace(/分頁\s*\d+\s*\/\s*\d+/g, '')
     .replace(/«.*?»/g, '')
     .replace(/試玩|聊天|辣妹|風月|搜尋|提供大量|每天更新/g, '')
     .replace(/\n{3,}/g, '\n\n')
     .trim();
// 去掉开头多余标题重复
let lines = t.split('\n');
while (lines.length > 0 && (lines[0].trim() === '' || lines[0].includes('href=') || lines[0].length < 5)) {
  lines.shift();
}
t = lines.join('\n').trim();
t;
